#include <vector>
#include <iostream>

void safe_access(std::vector<int>& v) {
    if (!v.empty()) { // Necessary precondition check
        int first = v.front();
        std::cout << "First element: " << first << std::endl;
    }
}

int main() {
    std::vector<int> data = {10, 20};
    safe_access(data);

    std::vector<int> empty_data;
